sql:
SELECT * FROM (
SELECT d.dept_code, COUNT(*) AS denominator, COUNT(*) FILTER (WHERE sr.status = 'Completed' AND sr.closed_at IS NOT NULL AND sr.closed_at - sr.created_at <= b.benchmark_days * INTERVAL '1 day') AS on_time_count, ROUND(COUNT(*) FILTER (WHERE sr.status = 'Completed' AND sr.closed_at IS NOT NULL AND sr.closed_at - sr.created_at <= b.benchmark_days * INTERVAL '1 day')::numeric / COUNT(*), 4) AS on_time_fraction FROM wh.service_request sr JOIN wh.department d ON d.id = sr.department_id JOIN wh.request_benchmark b ON LOWER(TRIM(b.sr_type)) = LOWER(TRIM(sr.sr_type)) WHERE d.dept_code IN ('CDOT', 'DSS') AND sr.is_duplicate = false AND sr.created_at >= '2026-07-01' AND sr.created_at < '2026-10-01' AND b.benchmark_days > 0 GROUP BY d.dept_code ORDER BY d.dept_code
) AS _guarded LIMIT 1000

